-- Sample data for tests and demos: the same shop as the MySQL fixtures, in PostgreSQL types.

CREATE TABLE customers (
  id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  email varchar(255) NOT NULL UNIQUE,
  full_name varchar(120) NOT NULL,
  country char(2) NOT NULL DEFAULT 'VN',
  created_at timestamp NOT NULL DEFAULT now()
);

CREATE TYPE order_status AS ENUM ('pending', 'paid', 'shipped', 'cancelled');

CREATE TABLE orders (
  id bigserial PRIMARY KEY,
  customer_id integer NOT NULL REFERENCES customers (id) ON DELETE CASCADE,
  status order_status NOT NULL DEFAULT 'pending',
  total numeric(12, 2) NOT NULL,
  note text,
  ordered_at timestamptz NOT NULL
);
CREATE INDEX idx_orders_status ON orders (status);
COMMENT ON COLUMN orders.note IS 'Written by the customer at checkout';

CREATE VIEW paid_orders AS SELECT * FROM orders WHERE status = 'paid';
CREATE MATERIALIZED VIEW order_totals AS
  SELECT customer_id, sum(total) AS total FROM orders GROUP BY customer_id;
CREATE SEQUENCE invoice_numbers;

CREATE FUNCTION order_count(customer integer) RETURNS bigint
  LANGUAGE sql STABLE AS 'SELECT count(*) FROM orders WHERE customer_id = customer';
CREATE PROCEDURE touch_customer(customer integer)
  LANGUAGE sql AS 'UPDATE customers SET full_name = full_name WHERE id = customer';
CREATE FUNCTION keep_row() RETURNS trigger LANGUAGE plpgsql AS 'BEGIN RETURN NEW; END';
CREATE TRIGGER customers_touch BEFORE UPDATE ON customers FOR EACH ROW EXECUTE FUNCTION keep_row();

