-- 5000 orders, enough to page and to hit the row limit.
INSERT INTO orders (customer_id, status, total, note, ordered_at)
SELECT 1 + i % 5,
       (ARRAY['pending', 'paid', 'shipped', 'cancelled'])[1 + i % 4]::order_status,
       round((i * 7.31)::numeric % 1000, 2),
       CASE WHEN i % 10 = 0 THEN 'gift wrap' END,
       timestamptz '2026-01-01 00:00:00+00' + i * interval '1 hour'
FROM generate_series(1, 5000) AS i;

REFRESH MATERIALIZED VIEW order_totals;
